base<-'/public3/labmember/qianqh/soil_amp_analysis/14_metabolic_functions';out<-file.path(base,'imeta_mes_20261025/author_code_only');.libPaths(c(file.path(base,'imeta_mes_20261025/Rlib'),.libPaths()));library(data.table)
