for(mode in names(patterns)){files<-list.files(file.path(out,'tables'),pattern=patterns[mode],full.names=TRUE);d<-rbindlist(lapply(files,fread));stopifnot(nrow(d)==expected[mode],all(d$n_random==1000),all(is.finite(d$MES)),all(is.finite(d$P)),all(d$P>=0&d$P<=1),sum(unique(d[,.(species,unit,cells)])$cells)==1708,!anyDuplicated(d[,.(species,unit,pathway_id)]));fwrite(d,file.path(out,'tables',paste0(mode,'_MES.tsv')),sep='\t');checks[[mode]]<-data.table(mode=mode,units=length(files),pathways_per_unit=45,results=nrow(d),cells_across_units=sum(unique(d[,.(species,unit,cells)])$cells),random_sets_each=1000);d[,analysis_unit_type:=mode];all[[mode]]<-d}
fwrite(rbindlist(checks),file.path(out,'reports/completeness_QA.tsv'),sep='\t');fwrite(rbindlist(all),file.path(out,'tables/all_author_MES.tsv'),sep='\t');print(rbindlist(checks))
input_files<-file.path(base,'inputs',c('analysis_objects.rds','state_key.tsv','pathway_catalogue.tsv'));dir.create(file.path(out,'provenance/inputs'),showWarnings=FALSE,recursive=TRUE);stopifnot(all(file.copy(input_files,file.path(out,'provenance/inputs'),overwrite=TRUE)));fwrite(data.table(original=input_files,md5=unname(tools::md5sum(input_files))),file.path(out,'provenance/input_manifest.tsv'),sep='\t')
